<?php
namespace App\Http\Controllers;
use App\Models\Competition; use Illuminate\Http\Request;
class CompetitionController extends Controller {
 public function index(Request $r){$q=Competition::where('status','published');if($r->filled('q')){$term=$r->string('q')->toString();$q->where(fn($x)=>$x->where('title','like',"%{$term}%")->orWhere('organizer','like',"%{$term}%")->orWhere('competition_category','like',"%{$term}%"));}foreach(['competition_category','competition_level','delivery_mode'] as $f)if($r->filled($f)&&$r->input($f)!=='Semua')$q->where($f,$r->input($f));if($r->filled('fee'))$r->input('fee')==='Gratis'?$q->where('fee_amount',0):$q->where('fee_amount','>',0);if($r->filled('status_filter')){$today=now()->toDateString();match($r->input('status_filter')){'Sedang Dibuka'=>$q->whereDate('registration_start','<=',$today)->whereDate('registration_end','>=',$today),'Segera Dibuka'=>$q->whereDate('registration_start','>',$today),'Segera Ditutup'=>$q->whereDate('registration_end','>=',$today)->whereDate('registration_end','<=',now()->addDays(7)->toDateString()),'Ditutup'=>$q->whereDate('registration_end','<',$today),default=>null};}match($r->input('sort','Terbaru')){'Terpopuler'=>$q->orderByDesc('views'),'Rating Tertinggi'=>$q->orderByDesc('rating'),default=>$q->latest()};$competitions=$q->paginate(9)->withQueryString();$categories=Competition::where('status','published')->select('competition_category')->distinct()->pluck('competition_category')->filter()->values();return view('competitions.index',compact('competitions','categories'));}
 public function show(Competition $competition){abort_unless($competition->status==='published',404);$competition->increment('views');return view('competitions.show',compact('competition'));}
 public function toggleFavorite(Competition $competition){if(!auth()->check())return redirect()->route('login')->with('status','Silakan login untuk menyimpan favorit.');$key='ajara_favorites';$f=collect(session($key,[]));if($f->contains($competition->id)){session([$key=>$f->reject(fn($id)=>$id==$competition->id)->values()->all()]);return back()->with('success','Lomba dihapus dari favorit.');}$f->push($competition->id);session([$key=>$f->all()]);return back()->with('success','Lomba ditambahkan ke favorit.');}
}
